src='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    original = [row[:] for row in g]

    # Find colored components (excluding the 5 marker) that touch each marker bar.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if original[r][c] not in (0, 5) and (r, c) not in seen:
                stack = [(r, c)]
                seen.add((r, c))
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and original[yy][xx] not in (0,5):
                            seen.add((yy,xx)); stack.append((yy,xx))
                comps.append(comp)

    # Each straight run of 5s repeats the adjacent colored tile along its length.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if original[r][c] == 5 and (c == 0 or original[r][c-1] != 5):
                e = c
                while e+1 < w and original[r][e+1] == 5: e += 1
                if e-c+1 >= 2: runs.append(('H', r, c, e))
                c = e+1
            else: c += 1
    for c in range(w):
        r = 0
        while r < h:
            if original[r][c] == 5 and (r == 0 or original[r-1][c] != 5):
                e = r
                while e+1 < h and original[e+1][c] == 5: e += 1
                if e-r+1 >= 2: runs.append(('V', c, r, e))
                r = e+1
            else: r += 1

    for orient, fixed, start, end in runs:
        for comp in comps:
            rs = [p[0] for p in comp]; cs = [p[1] for p in comp]
            r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
            # It must touch the side of this bar and lie alongside its span.
            if orient == 'V':
                if not (c0 == fixed+1 or c1 == fixed-1): continue
                if r1 < start or r0 > end: continue
                # Tile rows and columns are the component's bounding rectangle.
                period = r1-r0+1
                for y in range(start,end+1):
                    sy = r0 + ((y-r0) % period)
                    for x in range(c0,c1+1):
                        if original[sy][x] not in (0,5): g[y][x] = original[sy][x]
            else:
                if not (r0 == fixed+1 or r1 == fixed-1): continue
                if c1 < start or c0 > end: continue
                period = c1-c0+1
                for x in range(start,end+1):
                    sx = c0 + ((x-c0) % period)
                    for y in range(r0,r1+1):
                        if original[y][sx] not in (0,5): g[y][x] = original[y][sx]
    return g
'''
